// Auth: validate token + user balance. Tokens stored WITHOUT 'sk-' prefix.
const SB_URL='https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY='process.env.SUPABASE_SERVICE_ROLE_KEY||''';
const input=$input.first().json;
const headers=input.headers||{};
const authHeader=headers.authorization||headers.Authorization||'';
const token=authHeader.replace(/^Bearer\s+/i,'').trim();
const bodyToken=(input.body||input).token||'';
const effectiveToken=token||bodyToken;
const tokenKey=effectiveToken.replace(/^sk-/,'');
function authError(code,msg){return[{json:{_auth_error:true,error_code:code,message:msg}}]};
if(!effectiveToken)return authError('AUTH_INVALID','您未注册 pounding，请您至 api.mxou.cn 注册');
try{
const tResp=await this.helpers.httpRequest({method:'GET',url:SB_URL+'/rest/v1/tokens?select=id,user_id,status,remain_quota,unlimited_quota&key=eq.'+encodeURIComponent(tokenKey)+'&limit=1',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY},json:true,returnFullResponse:true,timeout:10000});
const rows=tResp.body||[];
if(!rows.length)return authError('AUTH_INVALID','您未注册 pounding，请您至 api.mxou.cn 注册');
const r=rows[0];
if(r.status===4)return authError('AUTH_EXHAUSTED','您的账户已欠费，请至 api.mxou.cn 充值');
if(r.status!==1)return authError('AUTH_DISABLED','您的账户已被禁用，请联系管理员');
let balance=0;
try{
const uResp=await this.helpers.httpRequest({method:'GET',url:SB_URL+'/rest/v1/users?id=eq.'+r.user_id+'&select=quota,used_quota&limit=1',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,Accept:'application/json'},json:true,returnFullResponse:true,timeout:10000});
const uRows=uResp.body||[];
if(uRows.length>0){const u=uRows[0];balance=(u.quota||0)-(u.used_quota||0);}
}catch(e){}
if(balance<=0&&!r.unlimited_quota)return authError('AUTH_EXHAUSTED','您的账户余额不足，请至 api.mxou.cn 充值');
// Claim task immediately to prevent Python worker race
  const tid = (input.body || input).task_id || '';
  if (tid) {
    try {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: SB_URL + '/rest/v1/gateway_tasks?task_id=eq.' + tid,
        headers: {
          apikey: SB_KEY,
          Authorization: 'Bearer ' + SB_KEY,
          'Content-Type': 'application/json',
          'Prefer': 'return=minimal'
        },
        body: { status: 'running' },
        json: true, timeout: 5000
      });
    } catch(e) {}
  }

  return $input.all().map(function(item){var j=item.json;j._sb_key=SB_KEY;j._sb_url=SB_URL;j._caller_user_id=r.user_id||'';j._caller_token_id=r.id||'';if(j.body&&typeof j.body=='object'){j.body._sb_key=SB_KEY;j.body._sb_url=SB_URL;j.body._caller_user_id=r.user_id||'';j.body._caller_token_id=r.id||'';}return{json:j};});
}catch(e){return authError('AUTH_ERROR','认证服务异常，请稍后重试');}

const inputJson=$input.first().json;if(inputJson._auth_error)return[{json:inputJson}];
const b=inputJson.body||inputJson;if(b._auth_error)return[{json:b}];
const SBK=inputJson._sb_key||b._sb_key||'';
const SBU=inputJson._sb_url||b._sb_url||'https://kekmppsuiiokdckdeolv.supabase.co';
const env=b.envelope||b;
const draft=env.draft||{};
const src=env.source||{};
const ext=env.extensions||{};
const resolved=env.resolved||{};
const clientCat=resolved.category||{};
const catIds=draft.source_category_ids||[];
const catQuery=b.category_query||draft.category_query||'';
const tid=b.task_id||('task-'+Date.now()+'-'+Math.floor(Math.random()*1000000));
const stages={};
let category=null;

// 1. 客户端已解析的类目
if(clientCat.description_category_id&&clientCat.type_id){
  category={description_category_id:String(clientCat.description_category_id),type_id:String(clientCat.type_id),confidence:parseFloat(clientCat.confidence||0.8),source:'client_resolved'};
  stages.Category='succeeded:client';
}

// 2. 从 source_category_ids 查询
if(!category&&catIds.length>0){
  const inFilter=catIds.map(function(id){return'"'+String(id)+'"'}).join(',');
  try{
    const resp=await this.helpers.httpRequest({method:'GET',url:SBU+'/rest/v1/category_mapping_verified?select=source_category_id,description_category_id,type_id,confidence&source_category_id=in.('+inFilter+')&order=confidence.desc&limit=5',headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,returnFullResponse:true,timeout:10000});
    const rows=resp.body||[];
    if(rows.length>0&&rows[0].description_category_id){
      category={description_category_id:String(rows[0].description_category_id),type_id:String(rows[0].type_id),confidence:parseFloat(rows[0].confidence||0),source:'supabase'};
      stages.Category='succeeded:catids';
    }
  }catch(e){stages.Category='supabase_failed'}
}

// 3. 从 category_query 查询（中文类目名匹配 + 标题模糊匹配）
if(!category&&catQuery){
  try{
    const resp=await this.helpers.httpRequest({method:'GET',url:SBU+'/rest/v1/category_mapping_verified?select=source_category_id,description_category_id,type_id,confidence&or=(source_category_id.eq.'+encodeURIComponent(catQuery)+',title.ilike.*'+encodeURIComponent(catQuery.replace(/'/g,'\'\''))+'*)&order=confidence.desc&limit=5',headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,returnFullResponse:true,timeout:10000});
    const rows=resp.body||[];
    if(rows.length>0&&rows[0].description_category_id){
      category={description_category_id:String(rows[0].description_category_id),type_id:String(rows[0].type_id),confidence:parseFloat(rows[0].confidence||0),source:'query_match'};
      stages.Category='succeeded:query';
    }
  }catch(e){}
}

// 4. 从学习记录推断类目（并补全 type_id）
if(!category){
  try{
    const resp=await this.helpers.httpRequest({method:'GET',url:SBU+'/rest/v1/ozon_attribute_mappings?select=category_id,confidence&confidence=gte.0.7&order=confidence.desc&limit=1',headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,timeout:10000});
    const rows=resp||[];
    if(rows.length>0&&rows[0].category_id){
      var cid=String(rows[0].category_id);
      var _tid='';
      // 查询 category_mapping_verified 获取 type_id
      try{
        var cmResp=await this.helpers.httpRequest({method:'GET',url:SBU+'/rest/v1/category_mapping_verified?select=description_category_id,type_id&description_category_id=eq.'+cid+'&limit=1',headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,timeout:10000});
        var cmRows=cmResp||[];
        if(cmRows.length>0){tid=String(cmRows[0].type_id||'');}
      }catch(e){}
      category={description_category_id:cid,type_id:tid,confidence:parseFloat(rows[0].confidence||0.5),source:'learned'};
      stages.Category=tid?'succeeded:learned':'succeeded:learned_no_type';
    }
  }catch(e){}
}

// 5. 无类目则阻断
if(!category){
  return[{json:{version:'v1',task_id:tid,stages:{Category:'blocked:no_category'},_blocked:true,tid:tid,_sb_key:SBK,_sb_url:SBU}}]
}

return[{json:{version:'v1',task_id:tid,stages:stages,category:category,envelope:env,ext:ext,draft:draft,src:src,tid:tid,_sb_key:SBK,_sb_url:SBU}}]

const cfg=$input.first().json;if(cfg._blocked||cfg.status==='blocked')return[{json:cfg}];
const SBK=cfg._sb_key||'';
const SBU=cfg._sb_url||'https://kekmppsuiiokdckdeolv.supabase.co';
const env=cfg.envelope||{};
const resolved=env.resolved||{};
const clientAttrs=resolved.attributes||[];
const draft=env.draft||{};
const cat=cfg.category||{};
const dcId=cat.description_category_id;
const ext=cfg.ext||{};
const token=ext.mxou_token||'';

if(!dcId){cfg.resolved_attrs=clientAttrs;cfg.stages.Attributes=clientAttrs.length>0?'client:'+clientAttrs.length:'no_category';return[{json:cfg}]}

// 1. 查询 Supabase 属性 schema
let sAttrs=[];
try{const u=SBU+'/rest/v1/ozon_category_attributes?select=attribute_id,is_required,attribute_name&category_id=eq.'+dcId+'&limit=200';const r=await this.helpers.httpRequest({method:'GET',url:u,headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,timeout:30000});sAttrs=r||[]}catch(e){sAttrs=[]}

if(!sAttrs.length){cfg.resolved_attrs=clientAttrs;cfg.stages.Attributes=clientAttrs.length>0?'client:'+clientAttrs.length:'no_schema';return[{json:cfg}]}

// 2. 查询字典值
const aIds=[...new Set(sAttrs.map(function(s){return''+s.attribute_id}))];
const dCache={};
for(const aid of aIds){try{const u=SBU+'/rest/v1/ozon_attribute_dictionary_values?select=dictionary_value_id,dictionary_value_info,dictionary_value_zh,dictionary_value_en&attribute_id=eq.'+aid+'&limit=200';const r=await this.helpers.httpRequest({method:'GET',url:u,headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,timeout:20000});dCache[aid]=r||[]}catch(e){dCache[aid]=[]}}

// 2.5 查询高置信度学习记录（闭合学习回路）
const learned={};
try{const u=SBU+'/rest/v1/ozon_attribute_mappings?select=attribute_id,source_value,mapped_value,dictionary_value_id,confidence&category_id=eq.'+dcId+'&confidence=gte.0.7&success_count=gte.1&order=confidence.desc&limit=100';const r=await this.helpers.httpRequest({method:'GET',url:u,headers:{apikey:SBK,Authorization:'Bearer '+SBK},json:true,timeout:15000});for(const m of(r||[])){if(!learned[m.attribute_id]||learned[m.attribute_id].confidence<m.confidence)learned[m.attribute_id]=m}}catch(e){}

// 3. 提取 1688 selling_points 作为额外上下文
const sellingPoints=(draft.selling_points||[]).map(function(sp){return sp.value||''}).filter(function(v){return v}).join(', ');

// 4. LLM 增强
let llmData=null;
if(token){
  try{
    const t1=draft.title||'';
    const d1=draft.description||'';
    const sp=sellingPoints?'\nSelling points: '+sellingPoints:'';
    const txt=(t1+' '+d1+sp).trim();
    if(txt.length>10){
      const r1=await this.helpers.httpRequest({method:'POST',url:'https://api.mxou.cn/v1/chat/completions',headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},body:{model:'deepseek-v4-flash',messages:[{role:'system',content:'Extract product attributes from the text below. Return a JSON object with EXACTLY these English keys: color, material, size, brand, gender, country, style, function. Values must be in Russian. If unknown, use null. Return ONLY the JSON object, nothing else.'},{role:'user',content:txt}],max_tokens:2000},json:true,timeout:30000});
      const c1=r1.choices&&r1.choices[0]&&r1.choices[0].message&&r1.choices[0].message.content;
      if(c1){const si=c1.indexOf('{');const ei=c1.lastIndexOf('}');if(si>=0&&ei>si)llmData=JSON.parse(c1.substring(si,ei+1));}
    }
  }catch(e){llmData=null}
}
// 5. 属性映射（含学习回路 + 非必填属性也填写）
const attrMap={'85':'brand','31':'brand','5309':'material','5307':'lining','10096':'color','9163':'gender','4389':'country','9382':'size','4501':'style','9024':'seller_code','5313':'pattern','4381':'season','5311':'function','5312':'trend'};
const draft1688=draft.attributes||{};
// 4.5 提取 CDP/enriched 属性（中文属性名→Ozon 属性映射）
const cdpAttrs=draft.attributes||[];
const cdpAttrMap={'材质':'5309','里料质地':'5307','功能':'5311','适用性别':'9163','品牌':'85','颜色':'10096','风格':'4501','适用场景':'5311','图案':'5313','容量':'9382','上市年份季节':'4381','有可授权的自有品牌':'85','皮质特征':'5309','容纳电脑尺寸':'9382','货号':'9024','流行元素':'5313','背负系统':'5311','季节':'4381','闭合方式':'5311','肩带样式':'5311'};
const cdpExtracted={};
for(const ca of cdpAttrs){
  const name=ca.name||'';
  const val=ca.value||'';
  if(!name||!val)continue;
  const mappedId=cdpAttrMap[name];
  if(mappedId){
    const field=attrMap[mappedId];
    if(field&&!cdpExtracted[field]){
      cdpExtracted[field]=val;
    }
  }
}



function extractAttr(aid,field){const v=cdpExtracted[field]||draft1688[field];if(v&&String(v).trim())return String(v).trim();return null}

function mV(s,dv){if(!s||!dv.length)return null;const sn=String(s).trim().toLowerCase();for(const v of dv){const ru=String(v.dictionary_value_info||'').trim().toLowerCase();const zh=String(v.dictionary_value_zh||'').trim().toLowerCase();const en=String(v.dictionary_value_en||'').trim().toLowerCase();if(ru===sn||zh===sn||en===sn)return v}for(const v of dv){const ru=String(v.dictionary_value_info||'').trim().toLowerCase();const zh=String(v.dictionary_value_zh||'').trim().toLowerCase();const en=String(v.dictionary_value_en||'').trim().toLowerCase();if(sn&&(ru.indexOf(sn)>=0||zh.indexOf(sn)>=0||en.indexOf(sn)>=0))return v}return null}

const val=[];const enr=[];
const defs={'85':'Другой','9163':'Мужской','4389':'Китай'};
const learningOps=[];
const itemId=cfg.tid||cfg.task_id||'';

for(const sa of sAttrs){
  const aid=''+sa.attribute_id;
  const iR=sa.is_required;
  const ca=clientAttrs.find(function(a){return''+a.id===aid});
  const dv=dCache[aid]||[];
  let resolved=null;
  let sourceType='unknown';
  let srcVal='';

  if(ca&&ca.values&&ca.values.length>0){
    resolved=ca;sourceType='client';
    if(dv.length>0&&!ca.values[0].dictionary_value_id){
      const m=mV(ca.values[0].value,dv);
      if(m){resolved={id:ca.id,values:[{dictionary_value_id:m.dictionary_value_id,value:m.dictionary_value_info}]};enr.push(aid);sourceType='dictionary'}
    }
  }else{
    const field=attrMap[aid];
    let v=null;


    // 如果值是中文，用 LLM 翻译后搜索字典
    if(v && /[\u4e00-\u9fa5]/.test(v) && dv.length > 0) {
      try {
        const transResp = await this.helpers.httpRequest({
          method:'POST',
          url:'https://api.mxou.cn/v1/chat/completions',
          headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},
          body:{model:'deepseek-v4-flash',messages:[
            {role:'system',content:'Translate Chinese to English. Return ONLY the translation, nothing else.'},
            {role:'user',content:v}
          ],max_tokens:500},
          json:true,
          timeout:15000
        });
        const transContent = transResp.choices && transResp.choices[0] && transResp.choices[0].message && transResp.choices[0].message.content;
        if(transContent) {
          const translated = transContent.trim().replace(/['"]/g, '');
          const m2 = mV(translated, dv);
          if(m2) {
            resolved = {id:parseInt(aid), values:[{dictionary_value_id:m2.dictionary_value_id, value:m2.dictionary_value_info}]};
            enr.push(aid);
            sourceType = 'llm_translate';
          }
        }
      } catch(e) {}
    }
    if(field){v=extractAttr(aid,field);if(v){sourceType='1688';srcVal=v}}

    if(!v&&llmData){const llmMap={'85':'brand','5309':'material','10096':'color','9163':'gender','4389':'country','9382':'size','4501':'style','5311':'function'};const llmKey=llmMap[aid];if(llmKey&&llmData[llmKey]){v=llmData[llmKey];sourceType='llm';srcVal=v}}

    if(!v&&learned[aid]){const lr=learned[aid];v=lr.mapped_value||lr.source_value;sourceType='learned';srcVal=lr.source_value||''}

    if(!v&&defs[aid]){v=defs[aid];sourceType='default';srcVal=v}

    if(v){
      const m=mV(v,dv);
      resolved={id:parseInt(aid),values:m?[{dictionary_value_id:m.dictionary_value_id,value:m.dictionary_value_info}]:[{value:v}]};
      if(m){enr.push(aid)}
    }
  }

  if(resolved){
    val.push(resolved);
    const vals=resolved.values||[];
    const dictId=vals[0]&&vals[0].dictionary_value_id||0;
    const mapVal=vals[0]&&vals[0].value||'';
    learningOps.push({item_id:itemId,category_id:dcId,attribute_id:aid,source_type:sourceType,source_value:srcVal,mapped_value:mapVal,dictionary_value_id:dictId,confidence:sourceType==='dictionary'?0.9:sourceType==='learned'?0.8:sourceType==='llm'?0.7:0.5,success_count:1,failure_count:0});
  }
}

// 6. 存储学习记录
if(learningOps.length>0){try{await this.helpers.httpRequest({method:'POST',url:SBU+'/rest/v1/ozon_attribute_mappings',headers:{apikey:SBK,Authorization:'Bearer '+SBK,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates'},body:learningOps,json:true,timeout:15000})}catch(e){}}

cfg.resolved_attrs=val;cfg._dict_enriched=enr;cfg._llm_data=llmData;cfg._selling_points=sellingPoints;cfg._learning_ops=learningOps.length;cfg.stages.Attributes='v:'+val.length+(enr.length?',e:'+enr.length:'')+',learn:'+learningOps.length;
return[{json:cfg}]

const cfg=$input.first().json;
const cleanRef=cfg._cleanRef||[];
const refs=((cfg.envelope||{}).assets||{}).image_urls||[];
const rawRefs=cleanRef.length>0?cleanRef.concat(refs.slice(0,3)):refs.slice(0,2);
const seen=new Set();
const refImages=rawRefs.filter(function(u){if(!u||seen.has(u))return false;seen.add(u);return true;});
const token=(cfg.ext||{}).mxou_token||(($getWorkflowStaticData('global').pipelineConfig||{}).ext||{}).mxou_token||'';
const draft=(cfg.envelope||{}).draft||{};
const title=draft.title||'';
const self=this;

// LLM: determine 3 best scenes for this product
var scenes=['室内','户外','社交'];
if(token&&title){
  try{
    var resp=await self.helpers.httpRequest({method:'POST',url:'https://api.mxou.cn/v1/chat/completions',
      headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},
      body:{model:'deepseek-v4-flash',messages:[
        {role:'system',content:'分析产品标题，推荐3个最适合的使用场景（俄语区电商风格）。返回JSON数组，每个元素是一个场景的中文简短描述（2-4个字）。只返回JSON数组，不要其他内容。示例：["卧室","浴室","梳妆台"]'},
        {role:'user',content:title}
      ],max_tokens:200},
      json:true,timeout:15000});
    var content=(resp.choices||[{}])[0].message||'';
    var llmText=typeof content==='string'?content:content.content||'';
    var jsonMatch=llmText.match(/\[[\s\S]*?\]/);
    if(jsonMatch){
      var parsed=JSON.parse(jsonMatch[0]);
      if(Array.isArray(parsed)&&parsed.length>=3){
        scenes=parsed.slice(0,3);
      }
    }
  }catch(e){}
}

var slots=[
  {n:'main_image',p:'根据参考图做一个俄罗斯电商主图，要符合俄罗斯人民审美，让产品点击率更高。严格保持参考图中的同一商品身份一致。画面以产品为主。'},
  {n:'multi_info',p:'根据参考图做一个俄罗斯电商产品多维信息图，用信息图方式展示产品容量、尺寸、结构、材质等关键信息。要符合俄罗斯人民审美。画面以产品为主。'},
  {n:'detail',p:'根据参考图做一个俄罗斯电商细节展示图，要符合俄罗斯人民审美。画面以产品为主。严格保持参考图中的同一商品身份一致。'},
  {n:'social_proof',p:'根据参考图做一个俄罗斯电商好评如潮图，要符合俄罗斯人民审美，让整体画面更有故事感，让产品点击率更高。严格保持参考图中的同一商品身份一致。'},
  {n:'scene_1',p:'根据参考图做一个俄罗斯电商使用场景图('+scenes[0]+'场景)，要符合俄罗斯人民审美，让产品点击率更高。严格保持参考图中的同一商品身份一致。画面以产品为主。'},
  {n:'scene_2',p:'根据参考图做一个俄罗斯电商使用场景图('+scenes[1]+'场景)，要符合俄罗斯人民审美。严格保持参考图中的同一商品身份一致。'},
  {n:'scene_3',p:'根据参考图做一个俄罗斯电商使用场景图('+scenes[2]+'场景)，要符合俄罗斯人民审美。严格保持参考图中的同一商品身份一致。'},
  {n:'comparison',p:'根据参考图做一个俄罗斯电商多维对比图，要符合俄罗斯人民审美。对比表达必须中性、克制、真实。严格保持参考图中的同一商品身份一致。'}
];

return slots.map(function(s){return{json:{_slot:s.n,_prompt:s.p,_token:token,_refs:refImages,_cfg:cfg}}});

const cfg=$input.first().json;const cat=cfg.category||{};const draft=cfg.draft||{};const src=cfg.src||{};const ext=cfg.ext||{};const images=cfg.image_results||{};const rawAttrs=cfg.resolved_attrs||[];const llmData=cfg._llm_data||{};const pricing=cfg._pricing||{};
const IMG_ORDER=['main_image','multi_info','detail','social_proof','scene_1','scene_2','scene_3','comparison','multi_angle','white_bg'];
const allImgs=IMG_ORDER.map(function(s){return images[s]}).filter(function(v){return v&&typeof v==='string'&&v.startsWith('http')});
const primaryImage=allImgs[0]||images.main_image||images.white_bg||'';
const imgs=allImgs.slice(0,10);
var descCatId=parseInt(cat.description_category_id);
var typeId=parseInt(cat.type_id);
if(!(descCatId>0&&typeId>0)){cfg.stages.Payload='blocked:no_valid_category';cfg._blocked=true;return[{json:cfg}]}
const finalPrice=pricing.price_final?String(pricing.price_final):String(draft.price||'100.00');

// 获取重量和尺寸（从 draft 或 enriched）
const weight=parseInt(draft.weight)||500;
const depth=parseInt(draft.depth)||100;
const width=parseInt(draft.width)||100;
const height=parseInt(draft.height)||200;

// SEO 标题
function buildSeoTitle(){
  var t=draft.title||'';
  if(!t)return'Новый товар';
  var hasCyrillic=/[\u0400-\u04FF]/.test(t);
  if(hasCyrillic){
