}

var finalData={store_id:ext.store_id||'',source_platform:ext.source_platform||'1688',product_url:(cfg.src||{}).source_url||'',listing_type:ext.listing_type||'new',title:(cfg.draft||{}).title||'',success:status==='succeeded',task_id:tid,ozon_task_id:cfg.ozon_task_id||null,stages:stages};

try{await this.helpers.httpRequest({method:'PATCH',url:SB_URL+'/rest/v1/gateway_tasks?task_id=eq.'+tid,headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},body:{status:status,result_json:finalData},json:true,timeout:10000});stages.Status='written'}catch(e){try{await this.helpers.httpRequest({method:'POST',url:SB_URL+'/rest/v1/gateway_tasks',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},body:{task_id:tid,status:status,result_json:finalData},json:true,timeout:10000});stages.Status='written'}catch(e2){stages.Status='write_failed:'+String(e2.message||e2).slice(0,80)}}

return[{json:{version:'v1',task_id:tid,status:status,_next_action:cfg._next_action||null,terminal:true,stages:stages,ozon_task_id:cfg.ozon_task_id||null}}]

const cfg=$input.first().json;
const ext=cfg.ext||{};
const env=(cfg.envelope||{});
const src=env.source||{};
const draft=env.draft||{};
const resolved=env.resolved||{};
const cat=cfg.category||{};
const tid=cfg.tid||cfg.task_id||'task';
const stages=cfg.stages||{};
const clientId=ext.ozon_client_id||'';
const apiKey=ext.ozon_api_key||'';
const token=ext.mxou_token||'';

if(!cfg.ozon_task_id){
  stages.AttrSelfCheck='skip:no_ozon_task';
  return [{json:cfg}];
}

const dcid=parseInt(cat.description_category_id||(resolved.category||{}).description_category_id)||0;
const typeId=parseInt(cat.type_id||(resolved.category||{}).type_id)||0;
if(!dcid||!typeId){
  stages.AttrSelfCheck='skip:no_category';
  return [{json:cfg}];
}

await new Promise(r=>setTimeout(r,10000));
const self=this;

// Get Ozon category attributes
let catAttrs=[];
try{
  const resp=await self.helpers.httpRequest({method:'POST',url:'https://api-seller.ozon.ru/v1/description-category/attribute',headers:{'Client-Id':clientId,'Api-Key':apiKey,'Content-Type':'application/json'},body:{description_category_id:dcid,type_id:typeId,language:'RU'},json:true,timeout:15000});
  catAttrs=resp.result||[];
}catch(e){
  // Try again with different timeout
  try{
    const resp=await self.helpers.httpRequest({method:'POST',url:'https://api-seller.ozon.ru/v1/description-category/attribute',headers:{'Client-Id':clientId,'Api-Key':apiKey,'Content-Type':'application/json'},body:{description_category_id:dcid,type_id:typeId,language:'RU'},json:true,timeout:30000});
    catAttrs=resp.result||[];
  }catch(e2){
    stages.AttrSelfCheck='skip:cat_attrs_failed';
    return [{json:cfg}];
  }
}

// Always build required defaults
let newAttrs=[];
let seenIds=new Set();

// Required defaults
const requiredDefaults={85:971223473,31:971223473,9163:22880,4389:'Китай',9048:src.source_item_id||tid};
for(const[aid,val]of Object.entries(requiredDefaults)){
  if(aid==='9048'){
    newAttrs.push({id:9048,values:[{value:String(val).slice(0,50)}]});
  }else if(typeof val==='number'){
    newAttrs.push({id:parseInt(aid),values:[{dictionary_value_id:val,value:''}]});
  }else{
    newAttrs.push({id:parseInt(aid),values:[{value:val}]});
  }
  seenIds.add(parseInt(aid));
}

// Get 1688 source attributes
const srcAttrs=(draft.attributes||[]).concat(draft.sku_attributes?Object.entries(draft.sku_attributes).map(([k,v])=>({name:k,value:Array.isArray(v)?v[0]:v})):[]);

// LLM mapping if we have source attrs and token
if(srcAttrs.length>0&&token){
  try{
    const attrList=srcAttrs.slice(0,25).map(a=>`${a.name||''}: ${a.value||''}`).join('\n');
    const catList=catAttrs.filter(a=>!seenIds.has(a.id)).slice(0,40).map(a=>`ID=${a.id}: ${a.name} (dict=${a.dictionary_id||0})`).join('\n');
    if(catList){
      const prompt=`Map 1688 Chinese product attributes to Ozon Russian attribute IDs.

1688 attributes:
${attrList}

Ozon attributes:
${catList}

Return JSON array: [{"ozon_id":<number>,"value":"<Russian translation>"}]
Translate Chinese values to Russian. Only confident mappings.`;

      const resp=await self.helpers.httpRequest({method:'POST',url:'https://api.mxou.cn/v1/chat/completions',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:{model:'deepseek-v4-flash',messages:[{role:'user',content:prompt}],max_tokens:1500},json:true,timeout:25000});
      const content=(resp.choices||[{}])[0].message||'';
      const llmText=typeof content==='string'?content:content.content||'';
      const jsonMatch=llmText.match(/\[[\s\S]*\]/);
      if(jsonMatch){
        const mappings=JSON.parse(jsonMatch[0]);
        for(const m of mappings){
          const ozonId=parseInt(m.ozon_id);
          if(!ozonId||seenIds.has(ozonId))continue;
          const val=m.value||'';
          if(!val)continue;
          const catAttr=catAttrs.find(a=>a.id===ozonId);
          const dictId=catAttr?catAttr.dictionary_id:0;
          let dictMatch=null;
          if(dictId){
            try{
              const dResp=await self.helpers.httpRequest({method:'POST',url:'https://api-seller.ozon.ru/v1/description-category/attribute/values/search',headers:{'Client-Id':clientId,'Api-Key':apiKey,'Content-Type':'application/json'},body:{attribute_id:ozonId,description_category_id:dcid,type_id:typeId,value:val,limit:5},json:true,timeout:10000});
              const candidates=dResp.result||[];
              if(candidates.length>0)dictMatch={id:candidates[0].id,value:candidates[0].value};
            }catch(e){}
          }
          if(dictMatch){
            newAttrs.push({id:ozonId,values:[{dictionary_value_id:dictMatch.id,value:dictMatch.value}]});
          }else{
            newAttrs.push({id:ozonId,values:[{value:val}]});
          }
          seenIds.add(ozonId);
        }
      }
    }
  }catch(e){}
}

// Add any remaining required attrs from category
for(const a of catAttrs){
  if(a.is_required&&!seenIds.has(a.id)){
    if(a.id===8229){
      // Type - get first value
      try{
        const vResp=await self.helpers.httpRequest({method:'POST',url:'https://api-seller.ozon.ru/v1/description-category/attribute/values',headers:{'Client-Id':clientId,'Api-Key':apiKey,'Content-Type':'application/json'},body:{attribute_id:8229,description_category_id:dcid,type_id:typeId,limit:3},json:true,timeout:10000});
        const vals=vResp.result||[];
        if(vals.length>0)newAttrs.push({id:8229,values:[{dictionary_value_id:vals[0].id,value:vals[0].value}]});
      }catch(e){}
    }else if(a.id===9782){
      newAttrs.push({id:9782,values:[{value:'0'}]});
    }else if(a.id===23487){
      newAttrs.push({id:23487,values:[{value:'Китай'}]});
    }
    seenIds.add(a.id);
  }
}

// Re-upload
if(newAttrs.length>2){
  try{
    const payload=cfg.payload||{};
    const items=payload.items||[];
    if(items.length>0){
      const item=items[0];
      // Merge with existing attrs
      const existingIds=new Set((item.attributes||[]).map(a=>a.id));
      const merged=[...(item.attributes||[])];
      for(const a of newAttrs){
        if(!existingIds.has(a.id))merged.push(a);
      }
      item.attributes=merged;
      await self.helpers.httpRequest({method:'POST',url:'https://api-seller.ozon.ru/v3/product/import',headers:{'Client-Id':clientId,'Api-Key':apiKey,'Content-Type':'application/json'},body:{items:[item]},json:true,timeout:30000});
      stages.AttrSelfCheck='done:'+merged.length+'_attrs';
    }
  }catch(e){
    stages.AttrSelfCheck='upload_failed:'+String(e.message||e).slice(0,50);
  }
}else{
  stages.AttrSelfCheck='skip:too_few_attrs';
}

return [{json:cfg}];

const cfg=$input.first().json;
const ext=cfg.ext||{};
const payload=cfg.payload||{};
const items=payload.items||[];
const stages=cfg.stages||{};
const self=this;

if(!cfg.ozon_task_id){
  stages.AttrUpdate='skip:no_task_id';
  return [{json:cfg}];
}

const item=items[0]||{};
const attrs=item.attributes||[];

if(!attrs.length){
  stages.AttrUpdate='skip:no_attrs';
  return [{json:cfg}];
}

// Wait for import to complete
await new Promise(r=>setTimeout(r,20000));

// Poll import task to get product_id
let productId=null;
for(let i=0;i<6;i++){
  try{
    const resp=await self.helpers.httpRequest({
      method:'POST',
      url:'https://api-seller.ozon.ru/v1/product/import/info',
      headers:{'Client-Id':ext.ozon_client_id,'Api-Key':ext.ozon_api_key,'Content-Type':'application/json'},
      body:{task_id:cfg.ozon_task_id},
      json:true,timeout:15000
    });
    const taskItems=(resp.result||{}).items||[];
    if(taskItems.length>0&&taskItems[0].product_id){
      productId=taskItems[0].product_id;
      break;
    }
  }catch(e){}
  await new Promise(r=>setTimeout(r,5000));
}

if(!productId){
  stages.AttrUpdate='skip:no_product_id';
  return [{json:cfg}];
}

// Re-send attributes with product_id
try{
  const updatePayload={
    items:[{
      product_id:productId,
      description_category_id:item.description_category_id,
      type_id:item.type_id,
      attributes:attrs
    }]
  };
  const resp=await self.helpers.httpRequest({
    method:'POST',
    url:'https://api-seller.ozon.ru/v3/product/import',
    headers:{'Client-Id':ext.ozon_client_id,'Api-Key':ext.ozon_api_key,'Content-Type':'application/json'},
    body:updatePayload,
    json:true,timeout:30000
  });
  const taskId=(resp.result||{}).task_id;
  stages.AttrUpdate=taskId?'succeeded:task_'+taskId:'FAIL:'+JSON.stringify(resp).slice(0,200);
}catch(e){
  stages.AttrUpdate='ERR:'+String(e.message||e).slice(0,100);
}

return [{json:cfg}];
